create table if not exists public.customers(id bigint generated by default as identity primary key,name text not null,email text not null,phone text not null);
create table if not exists public.water_bookings(id bigint generated by default as identity primary key,name text not null,email text not null,phone text not null,service text not null,address text not null,booking_date date not null,message text,created_at timestamptz default now());
create table if not exists public.contacts(id bigint generated by default as identity primary key,name text not null,email text not null,phone text,subject text not null,message text not null,created_at timestamptz default now());
alter table public.customers enable row level security; alter table public.water_bookings enable row level security; alter table public.contacts enable row level security;
create policy "public insert customers" on public.customers for insert to anon,authenticated with check(true); create policy "admins read customers" on public.customers for select to authenticated using(true);
create policy "public insert bookings" on public.water_bookings for insert to anon,authenticated with check(true); create policy "admins read bookings" on public.water_bookings for select to authenticated using(true);
create policy "public insert contacts" on public.contacts for insert to anon,authenticated with check(true); create policy "admins read contacts" on public.contacts for select to authenticated using(true);